<script type="text/javascript">

// 获取当前筛选日期
function getCurrentFilterDate() {
	// 获取年份
	var year = $('#year').text().replace(/[^0-9]/ig,"");

	// 获取月份并确保两位数格式
	var month = $('#month').text().replace(/[^0-9]/ig,"");
	month = month.padStart(2, '0'); // 确保月份是两位数

	// 获取日期并确保两位数格式
	var day = $('.single-slider').val().replace(/[^0-9]/ig,"");
	day = day.padStart(2, '0'); // 确保日期是两位数

	// 获取当前日期
	var today = new Date().getFullYear() + "-" + (new Date().getMonth() + 1).toString().padStart(2, '0') + "-" + new Date().getDate().toString().padStart(2, '0');

	// 构建选中的日期
	var selectedDate = year + "-" + month + "-" + day;

	// 返回日期信息对象
	return {
		year: year,
		month: month,
		day: day,
		selectedDate: selectedDate,
		today: today,
		isToday: (selectedDate === today)
	};
}

$(document).ready(function(){

	var p = 1;
	var isloading = 0;
	var isend = 0;

	loadDataByDate();

	// 更新导出按钮的函数
	function updateExportDate() {
		// 获取当前选中的年月日
		var year = $('#year').text().replace(/[^0-9]/ig,"");
		var month = $('#month').text().replace(/[^0-9]/ig,"").padStart(2, '0');
		var day = $('.single-slider').val().replace(/[^0-9]/ig,"").padStart(2, '0');
		var dateStr = year + '-' + month + '-' + day;

		// 更新导出按钮属性
		var $exportBtn = $('#export-date-btn');
		if ($exportBtn.length > 0) {
			$exportBtn.attr({
				'export-desc': '将 ' + dateStr + ' 当日上榜数据导出为文件，方便离线浏览或数据分析',
				'export-params': JSON.stringify({module: 'node', nodeid: window.nodeId, type: 'history', date: dateStr})
			});

			// 更新按钮文本
			$('#export-date-text').text('导出 ' + dateStr + ' 上榜数据');
		}
	}


	$('.dropdown-toggle').click(function(){
		$(this).parent().toggleClass("open");
	});

	// 点击页面空白区域关闭dropdown
	$(document).click(function(e){
		if(!$(e.target).closest('.dropdown-menu').length && !$(e.target).hasClass('dropdown-toggle') && !$(e.target).parent().hasClass('dropdown-toggle')){
			$('.dropdown-menu').parent().removeClass("open");
		}
	});

	$('#loadmore').click(function(){
		loadDataByDate();
	});

	changeY();
	$('.dropdown-menu li').click(function(){
		var name=$('a',this).text();
		$(this).parents('.btn-group').toggleClass("open");
		$(this).parents('.btn-group').find('.dropdown-toggle span').text(name);
		changeY();
		updateExportDate(); // 更新导出按钮文本
	});

	function changeY(){
		var year=$('#year').text().replace(/[^0-9]/ig,"")
		var month=$('#month').text().replace(/[^0-9]/ig,"")
		var d = new Date(year, month, 0);
		var days=d.getDate();
		var dayArr=[];
		for(var i=1;i<=days;i++)
		{
			dayArr.push(i+'');
		}
		var last=parseInt(dayArr[dayArr.length-1]);
		//$('.slider-container').remove();	
		if($('.slider-container').length > 0 ){
			$('.slider').children().remove();
			$('.slider').html('<input type="hidden" value="" class="single-slider none">');
		}

		p = 1;//第一页
		isloading = 0;
		isend = 0;

		$('.single-slider').jRange({
		    from:1,
		    to:last,
		    step: 1,
		    scale: dayArr,
		    format: '%s',
		    width:$('.slider').outerWidth()-20,
		    showLabels: true,
		    snap: true,
		    onstatechange:function () {
				p = 1;
				isloading = 0;
				isend = 0;
				$(".filter-data").empty();
				$('.snapshot-hours').empty();
				$('.snapshot-back-btn').click();

				// 获取当前筛选日期
				var dateInfo = getCurrentFilterDate();

